#!/usr/bin/env python3
from pathlib import Path
MARKER='<!-- GABON360-SATELLITE-PANEL-V1 -->'
PAYLOAD=r'''<!-- GABON360-SATELLITE-PANEL-V1 -->
<style>#g360-satellite-panel{position:fixed;right:14px;bottom:14px;z-index:99999;width:min(390px,calc(100vw - 28px));max-height:62vh;overflow:auto;background:rgba(8,16,28,.96);color:#eef6ff;border:1px solid rgba(77,170,255,.45);border-radius:16px;box-shadow:0 12px 36px rgba(0,0,0,.42);font:14px/1.4 system-ui,sans-serif}#g360-satellite-panel .h{display:flex;justify-content:space-between;padding:12px 14px;border-bottom:1px solid #ffffff1a}.g360-pill{font-size:11px;padding:3px 7px;border-radius:999px;background:#173b2a;color:#9ff0bf}.b{padding:12px 14px}.r{display:flex;gap:8px;margin-bottom:9px}.r select,.r button{border-radius:9px;border:1px solid #ffffff29;padding:8px;background:#152236;color:#fff}.s{font-size:12px;opacity:.82;margin:6px 0 10px}.c{padding:9px 10px;margin:7px 0;border-radius:10px;background:#ffffff0e;border:1px solid #ffffff14}.m{font-size:11px;opacity:.72}.n{font-size:11px;opacity:.68;margin-top:10px}</style>
<div id="g360-satellite-panel"><div class="h"><b>🛰️ Satellites — Gabon</b><span class="g360-pill">PUBLIC / CATALOGUE</span></div><div class="b"><div class="r"><select id="g360-sat-collection"><option value="sentinel-2-l2a">Sentinel-2 L2A</option><option value="sentinel-2-l1c">Sentinel-2 L1C</option><option value="sentinel-1-grd">Sentinel-1 GRD</option></select><button id="g360-sat-refresh" type="button">Actualiser</button></div><div id="g360-sat-status" class="s">Prêt à interroger Copernicus…</div><div id="g360-sat-results"></div><div class="n">Observations/catalogue reçues : pas de vidéo satellite continue, pas d'action automatique.</div></div></div>
<script>(function(){const E='https://stac.dataspace.copernicus.eu/v1/search',B=[8.5,-4,14.5,2.5],s=document.getElementById('g360-sat-status'),o=document.getElementById('g360-sat-results'),c=document.getElementById('g360-sat-collection'),b=document.getElementById('g360-sat-refresh');if(!s||!o||!c||!b)return;const x=v=>String(v??'').replace(/[&<>"']/g,q=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[q]));async function load(){s.textContent='Connexion au catalogue Copernicus…';o.innerHTML='';b.disabled=true;try{const r=await fetch(E,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({collections:[c.value],bbox:B,limit:8,query:{'eo:cloud_cover':{lte:60}}})});if(!r.ok)throw Error('HTTP '+r.status);const d=await r.json(),f=Array.isArray(d.features)?d.features:[];s.textContent=f.length+' observation(s) trouvée(s) — Copernicus CDSE';o.innerHTML=f.length?f.map(i=>{const p=i.properties||{},cl=p['eo:cloud_cover'];return '<div class="c"><b>'+x(i.id||'Observation')+'</b><div class="m">'+x(p.datetime||'date inconnue')+(cl!=null?' · nuages '+Number(cl).toFixed(1)+'%':'')+'</div></div>'}).join(''):'<div class="c">Aucune observation correspondante.</div>'}catch(e){s.textContent='Catalogue indisponible : '+e.message;o.innerHTML='<div class="c">Aucune donnée simulée ne sera affichée.</div>'}finally{b.disabled=false}}b.onclick=load;c.onchange=load;load()})();</script>
'''
for p in sorted(Path('android_project').rglob('index.html'),key=lambda p:('assets' not in p.parts,len(p.parts))):
    t=p.read_text(encoding='utf-8')
    if MARKER in t: print('already:',p); raise SystemExit(0)
    i=t.lower().rfind('</body>')
    if i<0: continue
    p.write_text(t[:i]+PAYLOAD+'\n'+t[i:],encoding='utf-8'); print('injected:',p); raise SystemExit(0)
raise SystemExit('No suitable index.html found')
